/*
 * A231875  Elements of the triassociative sub-operad Tri of TN generated by
 *          01, 10 and 11.
 * https://oeis.org/A231875
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 11, u16 n <= 26, u32 n <= 26, u64 n <= 26, u128 n <= 26,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A231875: all positive integers whose decimal representation
   consists only of the digits 1 and 2, and which are not composed solely
   of 1's.  The terms are given in increasing numeric order.  */

/* Return the nth term (n >= 1).  */
seq_t a(idx_t n) {
    /* Find the length L of the desired number */
    idx_t sum = 0;         /* cumulative count of numbers with length < L */
    seq_t pow2 = (seq_t)2; /* 2^1 */
    idx_t L = 1;
    seq_t countL = pow2 - (seq_t)1; /* numbers of length L */

    /* advance L until the cumulative count reaches or exceeds n */
    while ((idx_t)sum + (idx_t)countL < n) {
        sum += (idx_t)countL;
        L++;
        pow2 = pow2 * (seq_t)2;
        countL = pow2 - (seq_t)1;
    }

    /* offset of the n-th number among numbers of length L (0‑based) */
    idx_t offset0 = n - sum - 1;

    /* binary value that maps to the required digits (1↔0, 2↔1) */
    seq_t v = (seq_t)(offset0 + 1);

    /* build the decimal number from its digits */
    seq_t result = (seq_t)0;
    for (idx_t i = L; i > 0; --i) {
        seq_t bit = (v >> (i - 1)) & (seq_t)1;
        seq_t digit = bit ? (seq_t)2 : (seq_t)1;
        result = result * (seq_t)10 + digit;
    }
    return result;
}
